// Normalises whatever a buyer's agent sends into {name, version, ecosystem}.
//
// There is no single shape to expect. The same request, phrased the same way by
// the same model, arrives as a top-level name and version, as a list of
// objects, as a package.json map, or as "lodash@4.17.20". The ecosystem turns
// up as `ecosystem`, `package_manager`, or not at all. A paid worker is a public
// API with no docs and no support channel, so being liberal about the input is
// not sloppiness here, it is the job.
//
// The trap that cost real money: `dependencies` as an ARRAY still passes
// `typeof x === 'object'`, so a map-shaped reader runs Object.entries over it,
// builds a query for a package named "0", gets a clean answer from OSV, and
// reports "no vulnerabilities". Wrong question, confident answer, buyer charged.

const body = $input.first().json.body || {};
const input = body.input ?? body ?? {};

// OSV ecosystem names are case-sensitive and are not what people type.
const ECOSYSTEMS = {
  npm: 'npm', node: 'npm', nodejs: 'npm', yarn: 'npm', pnpm: 'npm',
  pypi: 'PyPI', pip: 'PyPI', python: 'PyPI', poetry: 'PyPI',
  go: 'Go', golang: 'Go',
  maven: 'Maven', gradle: 'Maven', java: 'Maven',
  cargo: 'crates.io', crates: 'crates.io', rust: 'crates.io', 'crates.io': 'crates.io',
  rubygems: 'RubyGems', gem: 'RubyGems', bundler: 'RubyGems', ruby: 'RubyGems',
  nuget: 'NuGet', dotnet: 'NuGet',
  composer: 'Packagist', packagist: 'Packagist', php: 'Packagist',
  hex: 'Hex', pub: 'Pub', conan: 'ConanCenter',
};

const declared = input.ecosystem || input.package_manager || input.packageManager || input.registry;
const defaultEco = ECOSYSTEMS[String(declared || 'npm').toLowerCase().trim()] || String(declared || 'npm');

const eco = (e) => (e ? (ECOSYSTEMS[String(e).toLowerCase().trim()] || String(e)) : defaultEco);
const ver = (v) => String(v).replace(/^[\^~>=<\s]+/, '').replace(/\s.*$/, '').trim();

/** One entry, from an object, a "name@version" string, or a [name, range] pair. */
function one(entry, key) {
  if (entry == null) return null;
  if (typeof entry === 'string') {
    // Either a range belonging to `key` (a package.json map), or "name@version".
    if (key) return { name: key, version: ver(entry), ecosystem: defaultEco };
    const m = entry.trim().match(/^(@?[\w./-]+?)[@\s]+v?([\d][\w.+-]*)$/);
    return m ? { name: m[1], version: m[2], ecosystem: defaultEco } : null;
  }
  if (typeof entry === 'object') {
    const name = entry.name || entry.package || entry.id || key;
    const version = entry.version || entry.range || entry.v;
    if (!name || !version) return null;
    return { name: String(name), version: ver(version), ecosystem: eco(entry.ecosystem || entry.package_manager) };
  }
  return null;
}

/** Anything list-shaped or map-shaped becomes a flat list of entries. */
function collect(v) {
  if (!v) return [];
  if (Array.isArray(v)) return v.map((e) => one(e, null));
  if (typeof v === 'object') return Object.entries(v).map(([k, e]) => one(e, k));
  if (typeof v === 'string') return [one(v, null)];
  return [];
}

let pkgs = [];
if (input.packages !== undefined) pkgs = collect(input.packages);
else if (input.dependencies !== undefined) pkgs = collect(input.dependencies);
else if (input.deps !== undefined) pkgs = collect(input.deps);
else if (Array.isArray(input)) pkgs = collect(input);
else if (input.name && input.version) pkgs = [one(input, null)];
else if (input.package && input.version) pkgs = [one(input, null)];
else if (typeof input === 'string') pkgs = collect(input);

pkgs = pkgs
  .filter((p) => p && p.name && p.version && p.version !== '[object Object]')
  .map((p) => ({ name: String(p.name), version: String(p.version), ecosystem: p.ecosystem || defaultEco }))
  .slice(0, 100);

if (!pkgs.length) {
  // The error carries what was actually received. A worker that says only
  // "bad input" makes its buyer guess, and its buyer is a language model that
  // will guess differently every time.
  throw new Error(
    'No package/version pairs found. Accepted: ' +
    '{"input":{"name":"lodash","version":"4.17.20"}}, ' +
    '{"input":{"dependencies":[{"name","version"}]}}, ' +
    '{"input":{"dependencies":{"lodash":"^4.17.20"}}}, ' +
    '{"input":{"packages":["lodash@4.17.20"]}}. ' +
    'Received: ' + JSON.stringify(input).slice(0, 250)
  );
}

return [{ json: {
  pkgs,
  queries: pkgs.map((p) => ({
    package: { name: p.name, ecosystem: p.ecosystem },
    version: String(p.version),
  })),
} }];

const item = $input.first().json;
const raw = item.data ?? item;

let osv;
try {
  osv = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (e) {
  throw new Error('OSV did not return JSON: ' + String(raw).slice(0, 300));
}

const pkgs = $('Build queries').first().json.pkgs;

// A scanner that cannot tell "found nothing" from "the lookup never ran" is
// worse than no scanner at all, because it sells a clean bill of health for a
// question it failed to ask. OSV answers querybatch with exactly one result per
// query, in order. Anything else means we do not know, and the only honest move
// is to fail loudly rather than return zero findings that look identical to a
// real all-clear.
const results = osv && osv.results;
if (!Array.isArray(results) || results.length !== pkgs.length) {
  throw new Error(
    'OSV returned ' + (Array.isArray(results) ? results.length : 'no') +
    ' result(s) for ' + pkgs.length + ' query/queries. Refusing to report a clean scan. ' +
    'Sent: ' + JSON.stringify($('Build queries').first().json.queries).slice(0, 200) +
    ' Got: ' + JSON.stringify(osv).slice(0, 300)
  );
}

const findings = [];
pkgs.forEach((p, i) => {
  const vulns = (results[i] && results[i].vulns) || [];
  if (vulns.length) {
    findings.push({
      package: p.name,
      version: p.version,
      advisories: vulns.map((v) => ({ id: v.id, url: 'https://osv.dev/vulnerability/' + v.id })),
    });
  }
});

// `scanned` and `checkedAt` are part of the product, not decoration: what is
// being bought is a dated statement about a specific set of versions.
return [{ json: { output: {
  scanned: pkgs.length,
  vulnerable: findings.length,
  findings,
  source: 'osv.dev',
  checkedAt: new Date().toISOString(),
} } }];
